        int ans = inf;
        int n = nums.size();
        int s = 0;
        for (int i = 0, j = 0; j < n; ++j) {
            s += nums[j];
            while (s >= target) {
                ans = min(ans, j - i + 1);
                s -= nums[i++];
            }
        }
        return ans == inf ? 0 : ans;
    }
};
